manifests.Cargo.toml:
[package]
name = "displays-mqtt-bridge"
version = "0.1.2"
edition = "2024"
repository = "https://github.com/open-mqtt-bridges/display"
homepage = "https://open-mqtt-bridges.github.io/display/"
license = "MIT"
description = "Control DDC/CI monitor brightness through MQTT"

[dependencies]
anyhow = "1.0.100"
clap = { version = "4.5.53", features = ["derive"] }
ddc-hi = { version = "0.4.1", default-features = false, features = ["ddc-i2c"] }
rumqttc = { version = "0.25.1", default-features = false, features = ["url", "use-native-tls"] }
serde = { version = "1.0.228", features = ["derive"] }
serde_json = "1.0.145"
serde_yaml = "0.9.34"
tracing = "0.1.41"
tracing-subscriber = { version = "0.3.20", features = ["env-filter"] }
tokio = { version = "1.48.0", features = ["macros", "rt-multi-thread", "sync", "time"] }
uuid = { version = "1.19.0", features = ["v4"] }

[patch.crates-io]
# ddc-hi currently requires nom 3.x. This compatible local patch removes syntax
# that newer Rust versions have made a future incompatibility warning.
nom = { path = "third_party/nom-3.2.1" }
